#!/usr/bin/env node
/**
 * Keep the DETERMINISTIC part of the work document's index in step with the issue
 * manifest — and print the live tracker view on demand without writing it anywhere.
 *
 * WHY THE SPLIT. This script used to mirror live tracker state (open/closed per lane)
 * into the work document. That mirror could only be refreshed AFTER an item closed,
 * which is after the change that closed it had already merged — so every finished
 * piece of work owed the repository a second commit whose only content was a
 * generated file. Worse, between the merge and that commit the document was wrong.
 * A mirror of state that lives outside the repository does not belong inside it.
 *
 * What stays in the document is the part the repository actually owns: the RESERVE
 * — low-priority items that are not tracker items yet. It is derived from the
 * manifest, so it is deterministic, needs no network, and `--check` can gate it in
 * CI without ever going stale on its own.
 *
 *   node scripts/sync-backlog-index.mjs           # rewrite the block (offline)
 *   node scripts/sync-backlog-index.mjs --check   # exit 1 if stale (CI, offline)
 *   node scripts/sync-backlog-index.mjs --emit    # print the LIVE view, write nothing
 *
 * `--emit` is the only mode that needs the `gh` CLI. Send it to a CI job summary, a
 * terminal, anywhere that is not a tracked file.
 */

import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

// Project specifics come from .dev-standards.json — see lib/config.mjs.
import { issueFlowConfig } from './lib/config.mjs';
const ROOT = process.cwd();
const CFG = issueFlowConfig(ROOT);
const BACKLOG = join(ROOT, CFG.workDocument);
const REPO = CFG.repo;
const CHECK = process.argv.includes('--check');
const EMIT = process.argv.includes('--emit');

const BEGIN = '<!-- issue-index:begin — generated by scripts/sync-backlog-index.mjs, do not edit by hand -->';
const END = '<!-- issue-index:end -->';

// Lane order: whatever the project configured, then cross-lane, then unlabelled — so
// nothing here hard-codes one project's lane names.
const configuredLanes = [...Object.keys(CFG.owners), 'both', 'untracked']
  .filter((l, idx, all) => all.indexOf(l) === idx);

let manifest = { issues: [], reserve: [] };
try {
  manifest = JSON.parse(readFileSync(join(ROOT, CFG.manifest), 'utf8'));
} catch (_) { /* manifest optional: the block is then empty */ }
const reserve = manifest.reserve || [];
const filedTitles = new Set((manifest.issues || []).map((i) => i.title));

// A promoted item is moved from `reserve` into `issues` (the issue-flow skill says so),
// so the manifest alone decides what is still in reserve. Matching on the manifest and
// not on live titles is what makes this block deterministic — and an entry left in both
// places shows up in BOTH lists, which is the drift `--emit` warns about below.
const pending = reserve.filter((r) => !filedTitles.has(r.title));

// ── The deterministic block ──────────────────────────────────────────────────
const lanesOf = (items) => [...new Set([...configuredLanes, ...items.map((i) => i.track)])];

const reserveLines = [];
if (pending.length) {
  reserveLines.push(`#### Reserve — ${pending.length} low-priority items, not tracker items yet`, '');
  reserveLines.push('_Promote one with `node scripts/seed-issues.mjs --only=<slug>`, then write its'
    + ` acceptance criteria into the item and move the entry into \`issues\`. Detail: \`${CFG.manifest}\`._`, '');
  for (const track of lanesOf(pending)) {
    const mine = pending.filter((r) => r.track === track);
    if (!mine.length) continue;
    reserveLines.push(`**${track}** (${mine.length})  ${mine.map((r) => `${r.slug} \`${r.size}\``).join(' · ')}`, '');
  }
} else {
  reserveLines.push('_The reserve is empty — every item in the manifest is a tracker item._', '');
}

const block = [
  BEGIN,
  '',
  `_Generated from \`${CFG.manifest}\` by \`node scripts/sync-backlog-index.mjs\` — the reserve only.`
    + ' Live state is deliberately NOT mirrored here (it would be wrong the moment an item closed):'
    + ` \`gh issue list -R ${REPO} --state open\`, or \`--emit\` for the full lane view._`,
  '',
  ...reserveLines,
  END,
].join('\n');

// ── --emit: the live view, to stdout ─────────────────────────────────────────
if (EMIT) {
  const issues = JSON.parse(execFileSync('gh', [
    'issue', 'list', '-R', REPO, '--state', 'all', '--limit', '500',
    '--json', 'number,title,state,labels',
  ], { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 }));

  const slugByTitle = new Map((manifest.issues || []).map((i) => [i.title, i.slug]));
  const labelNames = (i) => i.labels.map((l) => l.name);
  const trackOf = (i) => (labelNames(i).find((n) => n.startsWith('track/')) || '').split('/')[1] || 'untracked';
  // Priority labels are project vocabulary (issueFlow.labels.priorities, most-urgent
  // first) — hard-coding a P0/P1/P2 scheme here would silently mis-sort any project
  // that names its priorities differently. Unknown labels sort last, shown as '?'.
  const PRIORITIES = CFG.labels.priorities;
  const prioOf = (i) => labelNames(i).find((n) => PRIORITIES.includes(n)) || '?';
  const prioRank = (p) => (PRIORITIES.includes(p) ? PRIORITIES.indexOf(p) : PRIORITIES.length);

  const out = [];
  let open = 0, closed = 0;
  const lanes = [...new Set([...configuredLanes, ...issues.map(trackOf)])];
  for (const track of lanes) {
    const mine = issues.filter((i) => trackOf(i) === track);
    if (!mine.length) continue;
    mine.sort((a, b) => (prioRank(prioOf(a)) - prioRank(prioOf(b))) || (a.number - b.number));
    const cells = mine.map((i) => {
      const done = i.state === 'CLOSED';
      done ? closed++ : open++;
      // A closed item stays listed, struck through: the view doubles as the record of
      // what this backlog has actually shipped.
      const slug = slugByTitle.get(i.title);
      const label = `#${i.number} ${prioOf(i)}${slug ? ' ' + slug : ''}`;
      return done ? `~~${label}~~` : label;
    });
    const openCount = mine.filter((i) => i.state !== 'CLOSED').length;
    out.push(`**${track}** (${openCount} open / ${mine.length})  ${cells.join(' · ')}`, '');
  }
  console.log(`### Tracker — ${open} open · ${closed} closed · ${pending.length} in the reserve`);
  console.log('');
  console.log(out.join('\n'));
  console.log(reserveLines.join('\n'));

  // The one thing only the live view can see: an entry that was promoted but never
  // moved out of `reserve`, so it is counted twice.
  const liveTitles = new Set(issues.map((i) => i.title));
  const stale = pending.filter((r) => liveTitles.has(r.title));
  if (stale.length) {
    const one = stale.length === 1;
    console.error(`\nWARNING: ${stale.length} reserve entr${one ? 'y is' : 'ies are'} already`
      + ` ${one ? 'a tracker item' : 'tracker items'} — move ${one ? 'it' : 'them'} from`
      + ` \`reserve\` into \`issues\` in ${CFG.manifest}:`);
    for (const r of stale) console.error(`  - ${r.slug}`);
    process.exit(1);
  }
  process.exit(0);
}

// ── Write / check the block ──────────────────────────────────────────────────
// The block is only ever written between the two markers — the script does not guess
// where an index "should" go in a document it did not generate.
const src = readFileSync(BACKLOG, 'utf8');
const begin = src.indexOf(BEGIN);
const end = src.indexOf(END, begin + BEGIN.length);
if (begin < 0 || end < 0) {
  console.error(`No index markers in ${CFG.workDocument} — add them where the index should live:\n${BEGIN}\n${END}`);
  process.exit(1);
}
const next = src.slice(0, begin) + block + src.slice(end + END.length);

if (next === src) {
  console.log(`Reserve block already current (${pending.length} in the reserve).`);
  process.exit(0);
}
if (CHECK) {
  console.error(`reserve block in ${CFG.workDocument} is STALE — run: node scripts/sync-backlog-index.mjs`);
  process.exit(1);
}
writeFileSync(BACKLOG, next);
console.log(`${CFG.workDocument} reserve block updated — ${pending.length} in the reserve.`);
